type OrderPublisher interface{ Publish(ctx context.Context, o Order) error }

type amqpOrders struct{ ch *amqp.Channel }

func (a amqpOrders) Publish(ctx context.Context, o Order) error {
    body, _ := json.Marshal(o)
    return a.ch.PublishWithContext(ctx, "", "orders", false, false,
        amqp.Publishing{ContentType: "application/json", Body: body})
}

